import { harborProtocolOperations } from './openapi'

const operationById: Map<string, (typeof harborProtocolOperations)[number]> = new Map(
  harborProtocolOperations.map((operation) => [operation.operationId, operation])
)

const requireOperation = (operationId: string) => {
  const operation = operationById.get(operationId)
  if (!operation) throw new Error(`Unknown Harbor protocol operation: ${operationId}`)
  return operation
}

export function createHarborStainlessConfig() {
  const health = requireOperation('getHealth')
  const healthz = requireOperation('getHealthz')
  const execute = requireOperation('executePlugin')

  return {
    organization: {
      name: 'harbor',
      docs: 'https://tryharbor.ai/docs',
    },
    targets: {
      python: {
        package_name: 'harbor_sdk_generated',
      },
    },
    client_settings: {
      opts: {
        bearer_token: {
          type: 'string',
          auth: {
            security_scheme: 'bearerAuth',
          },
          read_env: 'HARBOR_API_KEY',
        },
      },
    },
    environments: {
      production: 'https://api.tryharbor.ai',
      staging: 'https://stagapi.tryharbor.ai',
    },
    resources: {
      health: {
        methods: {
          retrieve: `${health.method} ${health.path}`,
          retrieve_deep: `${healthz.method} ${healthz.path}`,
        },
      },
      runtime: {
        methods: {
          execute: `${execute.method} ${execute.path}`,
        },
      },
    },
  } as const
}

export function stringifyHarborStainlessConfig(): string {
  return `organization:
  name: harbor
  docs: https://tryharbor.ai/docs

targets:
  python:
    package_name: harbor_sdk_generated

client_settings:
  opts:
    bearer_token:
      type: string
      auth:
        security_scheme: bearerAuth
      read_env: HARBOR_API_KEY

environments:
  production: https://api.tryharbor.ai
  staging: https://stagapi.tryharbor.ai

resources:
  health:
    methods:
      retrieve: get /health
      retrieve_deep: get /healthz
  runtime:
    methods:
      execute: post /plugins/execute
`
}
